//! Emits the PHP tables this crate's `entrypoint php` discovery walks, parsed
//! from `packaging/languages.tsv` at build time (`MB.67.3`).
//!
//! One declaration, one reader: the file's `php` rows become
//! `LIBPHP_CANDIDATES`, `LIBPHP_PROBES`, `PER_MINOR_DIRS`, `NEWEST_PHP`,
//! `SUPPORTED_PHP` and the `supported_php_minor` helper. A version added to (or
//! withdrawn from) the TSV changes this crate on the next build, and no `8.x`
//! list lives in the source. The generated file is `include!`d by
//! `src/discovery.rs`; the freshness test parses the same TSV with the same
//! fragment and asserts the emitted values equal it.

include!("../../packaging/languages.rs.inc");

use std::fmt::Write as _;
use std::path::{Path, PathBuf};

fn main() {
    let root = workspace_root();
    let tsv = root.join("packaging/languages.tsv");
    let inc = root.join("packaging/languages.rs.inc");
    println!("cargo:rerun-if-changed={}", absolute(&tsv));
    println!("cargo:rerun-if-changed={}", absolute(&inc));
    println!("cargo:rerun-if-changed=build.rs");

    let rows = load(&tsv).unwrap_or_else(|err| panic!("blastit-view-php: {err}"));
    let php = rows_of(&rows, "php");
    if php.is_empty() {
        panic!(
            "blastit-view-php: {} declares no php row, so no shim can be named",
            tsv.display()
        );
    }
    let out_dir =
        std::env::var("OUT_DIR").unwrap_or_else(|_| panic!("blastit-view-php: cargo sets OUT_DIR"));
    let path = Path::new(&out_dir).join("languages.rs");
    std::fs::write(&path, emit(&php))
        .unwrap_or_else(|err| panic!("blastit-view-php: cannot write {}: {err}", path.display()));
}

/// The repository root, two directories above this crate.
fn workspace_root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .ancestors()
        .nth(2)
        .map(Path::to_path_buf)
        .unwrap_or_else(|| panic!("blastit-view-php: build.rs has no workspace root"))
}

/// The absolute spelling of `path`, for `cargo:rerun-if-changed`.
fn absolute(path: &Path) -> String {
    std::fs::canonicalize(path).map_or_else(
        |_| path.display().to_string(),
        |resolved| resolved.display().to_string(),
    )
}

/// The generated `$OUT_DIR/languages.rs`.
fn emit(php: &[&Row]) -> String {
    let mut names: Vec<String> = Vec::new();
    let mut directories: Vec<String> = Vec::new();
    for row in php {
        let version = &row.version;
        let digits = row.digits();
        names.push(format!("libphp{version}.so"));
        names.push(format!("libphp-{version}.so"));
        names.push(format!("libphp{digits}.so"));
        directories.push(row.slug().to_string());
    }
    names.push("libphp.so".to_string());

    let mut out = String::new();
    out.push_str("// @generated by build.rs from packaging/languages.tsv. Do not edit.\n");
    out.push_str("//\n// Newest minor first, and every spelling of one minor together, exactly as the\n// `php` rows of `packaging/languages.tsv` declare them.\n\n");

    out.push_str("/// The distro file names a host NTS `libphp` is looked for under, newest first.\n///\n/// A fixed list rather than a directory scan: the order *is* the preference, so\n/// a newer library somebody dropped into a directory never changes which\n/// library an older host embeds. The unversioned `libphp.so` is last here\n/// because on its own it states no minor; the per-minor directory it sits in\n/// states one, which is why [`LIBPHP_PROBES`] also tries it there.\n");
    let _ = writeln!(
        out,
        "pub const LIBPHP_CANDIDATES: [&str; {}] = [",
        names.len()
    );
    for name in &names {
        let _ = writeln!(out, "    {},", quote(name));
    }
    out.push_str("];\n\n");

    out.push_str("/// The order the search walks: version-major, then spelling.\n///\n/// Each minor's own spellings are all tried before the next minor's, so the\n/// newest library wins rather than the first name in a list. The unversioned\n/// `libphp.so` in the plain directories stays last: its minor is only known\n/// from the descriptor's link target or the object's own bytes, so it is a\n/// fallback, not a preference.\n");
    let probe_count = php.len() * 4 + 1;
    let _ = writeln!(
        out,
        "pub const LIBPHP_PROBES: [LibphpProbe; {probe_count}] = ["
    );
    for row in php {
        let version = &row.version;
        let digits = row.digits();
        for name in [
            format!("libphp{version}.so"),
            format!("libphp-{version}.so"),
            format!("libphp{digits}.so"),
        ] {
            let _ = writeln!(
                out,
                "    LibphpProbe {{ name: {}, per_minor_dir: None }},",
                quote(&name)
            );
        }
        let _ = writeln!(
            out,
            "    LibphpProbe {{ name: \"libphp.so\", per_minor_dir: Some({}) }},",
            quote(row.slug())
        );
    }
    out.push_str("    LibphpProbe {\n        name: \"libphp.so\",\n        per_minor_dir: None,\n    },\n];\n\n");

    let (major, minor) = split(&php[0].version);
    out.push_str("/// The newest declared minor: the package a refusal names when the object\n/// states no version.\n");
    let _ = writeln!(
        out,
        "pub const NEWEST_PHP: PhpVersion = PhpVersion::new({major}, {minor});\n"
    );

    out.push_str("/// The declared minors this build ships a shim for, as one sentence.\n///\n/// A refused host reads exactly this sentence, and it names only rows of\n/// `packaging/languages.tsv`.\n");
    let ordered: Vec<&str> = php.iter().map(|row| row.version.as_str()).collect();
    let _ = writeln!(
        out,
        "pub const SUPPORTED_PHP: &str = {};\n",
        quote(&sentence("PHP", &ascending(&ordered)))
    );

    let directory_literals: Vec<String> = directories.iter().map(|name| quote(name)).collect();
    out.push_str("/// The per-minor embed directories a distro installs `libphp.so` into,\n/// newest first.\n");
    let _ = writeln!(
        out,
        "pub const PER_MINOR_DIRS: [&str; {}] = [{}];\n",
        directories.len(),
        directory_literals.join(", ")
    );

    out.push_str("/// Whether `(major, minor)` is one of the minors `packaging/languages.tsv`\n/// declares.\n");
    out.push_str("pub(crate) const fn supported_php_minor(major: u8, minor: u8) -> bool {\n    matches!((major, minor), ");
    let mut arms: Vec<String> = Vec::new();
    for row in php {
        let (major, minor) = split(&row.version);
        arms.push(format!("({major}, {minor})"));
    }
    out.push_str(&arms.join(" | "));
    out.push_str(")\n}\n\n");

    out.push_str("/// The `slug` column for one declared minor: the `libblastit_<slug>` infix\n/// stage 0 looks for.\n");
    out.push_str("pub(crate) const fn php_slug(major: u8, minor: u8) -> Option<&'static str> {\n    match (major, minor) {\n");
    for row in php {
        let (major, minor) = split(&row.version);
        let _ = writeln!(
            out,
            "        ({major}, {minor}) => Some({}),",
            quote(row.slug())
        );
    }
    out.push_str("        _ => None,\n    }\n}\n");

    out
}

/// A Rust string literal for `value`.
fn quote(value: &str) -> String {
    format!("{value:?}")
}

/// `"8.6"` as `(8, 6)`.
fn split(version: &str) -> (u8, u8) {
    let (major, minor) = version
        .split_once('.')
        .unwrap_or_else(|| panic!("packaging/languages.rs.inc parsed a version without a dot"));
    let major = major
        .parse()
        .unwrap_or_else(|_| panic!("packaging/languages.rs.inc parsed a non-numeric major"));
    let minor = minor
        .parse()
        .unwrap_or_else(|_| panic!("packaging/languages.rs.inc parsed a non-numeric minor"));
    (major, minor)
}
